#if APP_TESTS
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;
namespace FileCompass {internal static class DiskToolsUxTests {
 internal static int Run(string root){Directory.CreateDirectory(root);var log=new List<string>();var windows=new List<Window>();string motif=AppearanceTheme.Motif,mode=AppearanceTheme.Mode;Action<bool,string> check=(yes,text)=>{if(!yes)throw new Exception(text);log.Add(text);};try{SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));L.ChangeLanguage("cs");FluentTheme.Ensure();var folder=Directory.CreateDirectory(Path.Combine(root,"Dokumenty")).FullName;for(int i=0;i<8;i++)File.WriteAllText(Path.Combine(folder,"dokument-"+i+".txt"),new string('x',1000+i*500));
 foreach(string style in new[]{"Classic","Clean"})foreach(string color in new[]{"Light","Dark"}){AppearanceTheme.SetMotif(style);AppearanceTheme.Apply(color);var analyzer=new DiskAnalyzerWindow(null,folder,null,true);windows.Add(analyzer);Open(analyzer);NavigationTests.Wait(analyzer.ScanTask);analyzer.UpdateLayout();Verify(analyzer,L.Text("analyzer.title"),check);check(analyzer.Result.Root.Files==8&&analyzer.Chart.ActualHeight>=100,style+color+": analyzer retains data and usable chart");NextStageTests.Draw(analyzer,Path.Combine(root,style+"-"+color+"-analyzer.png"));analyzer.Close();windows.Remove(analyzer);
 var smart=new DiskSmartWindow(null,false);windows.Add(smart);Open(smart);var disk=SmartDisk.Parse("/dev/fixture","nvme","{\"device\":{\"protocol\":\"NVMe\"},\"model_name\":\"KINGSTON NVMe – ukázka\",\"smart_status\":{\"passed\":true},\"user_capacity\":{\"bytes\":1024209543168},\"nvme_smart_health_information_log\":{\"temperature\":51,\"percentage_used\":6,\"available_spare\":100,\"media_errors\":0}}");smart.SetResults(new List<SmartDisk>{disk});NavigationTests.Wait(Task.Delay(140));smart.UpdateLayout();Verify(smart,L.Text("smart.title"),check,false);check(smart.Snapshot!=null&&smart.Snapshot.Attributes.Count>0&&smart.HealthValue.IsVisible&&smart.TemperatureValue.IsVisible,style+color+": SMART preserves health, temperature and attributes");NextStageTests.Draw(smart,Path.Combine(root,style+"-"+color+"-smart.png"));smart.Close();windows.Remove(smart);
 }File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"PASS: "+log.Count+" checks"}));return 0;}catch(Exception ex){File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"FAIL: "+ex}));return 1;}finally{foreach(var w in windows)w.Close();AppearanceTheme.SetMotif(motif);AppearanceTheme.Apply(mode);}}
 static void Open(Window w){w.WindowStartupLocation=WindowStartupLocation.Manual;w.Left=-18000;w.Top=-18000;w.ShowActivated=false;w.ShowInTaskbar=false;w.Show();w.UpdateLayout();}
 static void Verify(Window w,string title,Action<bool,string> check,bool heading=true){check(FluentUiTests.Children<TextBlock>(w).Any(x=>x.FontSize==20&&x.Text==title&&x.IsVisible)==heading,title+": header matches intended layout");var frame=(FrameworkElement)w.Content;var close=FluentUiTests.Children<Button>(w).Single(x=>Convert.ToString(x.Content)==L.Text("action.close"));check(close.TransformToAncestor(frame).Transform(new Point(0,close.ActualHeight)).Y<=frame.ActualHeight,title+": footer actions remain reachable");}
}}
#endif
